using System.Runtime.InteropServices;
using System.Text.Json.Nodes;
using Avalonia;
using Avalonia.Headless;
using Avalonia.Threading;
using Prism.Commands;
using Prism.Core;
using Prism.Core.Cam;
using Prism.Kernel;
using Prism.Simulation;

AppBuilder.Configure<Application>().UseHeadless(new AvaloniaHeadlessPlatformOptions()).SetupWithoutStarting();
NativeSearch.Initialize();int checks=0;
void Check(bool value,string text){if(!value)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
void Reject(Action action,string text){try{action();}catch(InvalidOperationException){Check(true,text);return;}throw new Exception(text);}
var root=Path.GetFullPath("docs/workflow-studies");Directory.CreateDirectory(root);
var s=new CadSession();var body=s.AddObject(Occ.Box(10,10,20),"Workflow block",ObjKind.Solid);s.Update(body.Id,o=>o.WithMaterial(Materials.Find("6061")!));body=s.Find(body.Id)!;
var faces=Enumerable.Range(0,6).OrderBy(i=>body.Shape.Sub(SubKind.Face,i).Props().Center.Z).ToArray();
var st=s.NewStudy(body);st.ElementSize=4;st.Fixtures.Add(new Fixture{Faces=[new(body.Id,faces[0])]});st.Loads.Add(new Load{Kind=LoadKind.Force,Faces=[new(body.Id,faces[^1])],Value=100,Direction=Vec3.UnitZ});
string unrefinedSignature=StudySetup.Signature(body);File.WriteAllText(Path.Combine(root,"unrefined.brep"),body.Shape.ToBrep());body.Shape.Tessellate(.015);File.WriteAllText(Path.Combine(root,"refined.brep"),body.Shape.ToBrep());Check(StudySetup.Signature(body)==unrefinedSignature,"display remeshing does not change exact geometry provenance");
s.FaceSets.Add(new("Support",body.Id,[faces[0]],StudySetup.Signature(body)));
s.CaeCases.Add(new("Thermal reference",body.Id,new(CaeKind.SteadyThermal,[faces[0]],[faces[^1]],ElementSize:4),StudySetup.Signature(body)));
s.CamSetup=new("Test stock",body.Id,StudySetup.Signature(body),[-6,-6,0],[6,6,21],[-6,-6,21]);s.CamSetup.Validate(body);
var path=new ToolpathInfo("Test path","6 mm end mill",6,60,30,12000,26,[0,0,26,0,10,0,26,0,10,0,20,2,0,0,20,1],[0],false,false,SetupBody:body.Id,SourceSignature:StudySetup.Signature(body),Sources:new(){{body.Id,StudySetup.Signature(body)}},SetupSignature:s.CamSetup.Signature());
var pathObj=s.AddObject(Occ.Line(Vec3.Zero,new(0,0,.01)),"Path",ObjKind.Toolpath);s.Update(pathObj.Id,o=>o.WithAsm(path));
string file=Path.Combine(root,"workflow-roundtrip.prism");s.Save(file);var opened=new CadSession();opened.Open(file);
Check(opened.Find(body.Id)!=null,"body identities survive save/reopen");
Check(opened.ActiveStudy?.Id==st.Id&&opened.Studies.Count==1,"active static setup survives save/reopen");
var actual=opened.ActiveStudy!;Check(actual.Fixtures.Single().Faces.Single().Obj==body.Id&&actual.Loads.Single().Direction==Vec3.UnitZ&&actual.Loads.Single().Value==100,"boundary references and load vectors roundtrip");
Check(actual.ElementSize==4&&actual.Results==null,"mesh size is saved while native result handles are excluded");
Check(opened.FaceSets.Single().Faces.Single()==faces[0]&&opened.CaeCases.Single().Settings.FirstFaces.Single()==faces[0],"named selections and thermal settings roundtrip");
File.WriteAllText(Path.Combine(root,"brep-before.txt"),body.Shape.ToBrep());File.WriteAllText(Path.Combine(root,"brep-after.txt"),opened.Find(body.Id)!.Shape.ToBrep());
StudySetup.Validate(opened.Find(body.Id)!,actual.ShapeSignature,[faces[0]]);Check(true,"unchanged B-rep signatures survive serialization");
opened.CamSetup!.Validate(opened.Find(body.Id)!);CamValidation.Validate(opened,(ToolpathInfo)opened.Find(pathObj.Id)!.Asm!);Check(true,"stock setup and path source provenance survive serialization");
opened.Update(body.Id,o=>o.WithColor(0xFFEE5544));CamValidation.Validate(opened,(ToolpathInfo)opened.Find(pathObj.Id)!.Asm!);Check(true,"cosmetic changes do not stale toolpath geometry");
opened.CamSetup=opened.CamSetup with{Feed=900};Reject(()=>CamValidation.Validate(opened,(ToolpathInfo)opened.Find(pathObj.Id)!.Asm!),"changed setup invalidates its operation");
opened.CamSetup=s.CamSetup;opened.Update(body.Id,o=>o.WithShape(Occ.Box(11,10,20)));Reject(()=>StudySetup.Validate(opened.Find(body.Id)!,actual.ShapeSignature,[faces[0]]),"edited geometry rejects saved face indices");Reject(()=>CamValidation.Validate(opened,(ToolpathInfo)opened.Find(pathObj.Id)!.Asm!),"edited geometry rejects stale toolpaths");
Reject(()=>(s.CamSetup with{StockMax=[1,1,1]}).Validate(body),"undersized stock rejected");
var legacy=JsonNode.Parse(File.ReadAllText(file))!.AsObject();foreach(string field in new[]{"Studies","FaceSets","CaeCases","ActiveStudy","CamSetup"})legacy.Remove(field);legacy["Version"]=1;foreach(var o in legacy["Objects"]!.AsArray())o!.AsObject().Remove("Id");string old=Path.Combine(root,"legacy-model.prism");File.WriteAllText(old,legacy.ToJsonString());var legacySession=new CadSession();legacySession.Open(old);Check(legacySession.Objects.Count==2&&legacySession.Studies.Count==0,"legacy geometry files still load");
var timeline=new PathTimeline(path);Check(Math.Abs(timeline.Duration-(10.0/5000*60+6.0/30*60+10.0/60*60))<1e-9,"playback time distinguishes rapid, plunge and cutting feeds");
Check(timeline.At(timeline.Duration).tip==new Vec3(0,0,20)&&timeline.At(-1).tip==new Vec3(0,0,26),"playhead endpoints clamp correctly");
Check(timeline.At(timeline.Seconds[1]+6).tip.DistanceTo(new(10,0,23))<1e-8,"feed-based interpolation locates a mid-plunge tool tip");
Reject(()=>new PathTimeline(path with{Feeds=[60]}),"incomplete per-move feed arrays rejected");
Reject(()=>new PathTimeline(path with{Moves=[0,0,0,0,1,0,0,260]}),"out-of-range move codes rejected");
Reject(()=>new PathTimeline(path with{LayerStarts=[0,2,1]}),"unordered layer offsets rejected");
Reject(()=>CamValidation.Validate(s,path with{Moves=[0,0,10,0,10,0,10,0],SetupSignature=null,Sources=null,SetupBody=null}),"lateral rapid below clearance rejected");
var nc=Post.Cnc([path],Controller.GRBL,s.CamSetup.Origin(),"Test");Check(nc.Contains("G0 Z5")&&nc.Contains("G54"),"post subtracts the saved stock-top G54 origin");
var printOnly=new CadSession();var nozzleObj=printOnly.AddObject(Occ.Line(Vec3.Zero,new(0,0,.01)),"Nozzle path",ObjKind.Toolpath);printOnly.Update(nozzleObj.Id,o=>o.WithAsm(path with{IsPrint=true,Moves=[100,200,1,0,120,220,2,3]}));printOnly.ZoomExtents();Check(printOnly.Camera.Target.X==110&&printOnly.Camera.Target.Y==210,"zoom extents fits paths even without a model body");
var playbackPanel=new CamPlaybackCommand();printOnly.StartCommand(playbackPanel);Check(playbackPanel.PanelSettings[0].Label=="Operation","operation selector appears before playback controls");printOnly.CancelCommand();
var largeMoves=new double[50001*4];for(int i=0;i<50001;i++){largeMoves[i*4]=i*.001;largeMoves[i*4+3]=1;}var sparseOverlay=new Overlay();printOnly.DrawToolpath(sparseOverlay,path with{Moves=largeMoves},false);Check(sparseOverlay.Lines.Count<=20000&&sparseOverlay.Lines.All(line=>Math.Abs(line.B.X-line.A.X)<=.001001),"large paths render a bounded sparse overview without invented connecting chords");
var imported=LinearGcode.Parse("G21\nG90\nM82\nG92 E0\nG0 X10 Y10 Z.2 F600\nG1 X20 E1 F1200\nG1 Y20 E2\nG92 E0\nG1 X10 E1\nG0 Z.4\nG1 Y10 E2");
Check(imported.Path.MoveCount==7&&imported.Path.LayerCount==2,"external linear nozzle path and extrusion layers parsed");
Check(imported.Path.Move(2).kind==MoveKind.OuterWall&&imported.Path.Move(4).kind==MoveKind.OuterWall,"G92 extrusion reset preserves extrusion classification");
Check(imported.Path.FeedAt(1)==600&&imported.Path.FeedAt(2)==1200,"per-move feeds retained");
var relative=LinearGcode.Parse("G91\nG1 X10 E1\nG1 X-2 E.5\nG90\nM83\nG1 X20 E.2").Path;Check(relative.Move(2).x==8&&relative.Move(3).x==20&&relative.Move(3).kind==MoveKind.OuterWall,"relative coordinates and M83 extrusion supported");
var shifted=LinearGcode.Parse("G1 X10 F600\nG92 X0\nG1 X5").Path;Check(shifted.Move(2).x==15,"G92 shifts program zero without teleporting physical position");
Check(Math.Abs(LinearGcode.Parse("G20\nG1 X1 F60").Path.Move(1).x-25.4)<1e-9,"inch coordinates convert to millimeters");
Check(LinearGcode.Parse("M83\nG1 X10 E1\nG90\nG1 X20 E.5").Path.Move(2).kind==MoveKind.Rapid,"Marlin G90 clears extrusion-mode override");
foreach(string bad in new[]{"G2 X1 I2","G29","G1 A5 X1","G1 Xbanana","G1 X1 F0","G1 X1\nG28","T1\nG1 X1","G1 X1000001"})Reject(()=>LinearGcode.Parse(bad),"unsupported or malformed G-code rejected: "+bad.Replace('\n',' '));
var convergence=new ConvergenceCommand();s.StartCommand(convergence);convergence.Params.OfType<NumberParam>().Single().Value=5;string csv=Path.Combine(root,"convergence.csv");convergence.Params.OfType<TextParam>().Single().Value=csv;convergence.Params.OfType<ActionParam>().Single(a=>a.Label=="Compare three meshes").Run();var until=DateTime.UtcNow.AddSeconds(90);while(!File.Exists(csv)&&DateTime.UtcNow<until){Dispatcher.UIThread.RunJobs();Thread.Sleep(20);}Dispatcher.UIThread.RunJobs();
Check(File.Exists(csv)&&File.ReadAllLines(csv).Length==4,"three real static meshes produce a convergence CSV");
var samples=File.ReadAllLines(csv).Skip(1).Select(l=>l.Split(',')).ToArray();Check(samples.Select(row=>int.Parse(row[1])).SequenceEqual(samples.Select(row=>int.Parse(row[1])).Order()),"refinement increases mesh node counts");
double analytical=100*20/(68900.0*100);Check(samples.All(row=>Math.Abs(double.Parse(row[2],System.Globalization.CultureInfo.InvariantCulture)-analytical)/analytical<.15),"all refinement levels agree with axial beam displacement");s.CancelCommand();
Console.WriteLine($"SUCCESS: {checks} checks");
static class NativeSearch{[DllImport("kernel32",CharSet=CharSet.Unicode)]static extern bool SetDllDirectory(string path);public static void Initialize()=>SetDllDirectory(Path.GetFullPath("native/bin"));}
